class Solution:
    def demo(self, nums):
        seen = set()
        for x in nums:
            if x in seen:  # viz:check
                return True
            seen.add(x)  # viz:add
        return False

class Solution:
    def demo(self, nums, target):
        l, r = 0, len(nums) - 1
        while l < r:
            s = nums[l] + nums[r]  # viz:sum
            if s == target:
                return [l, r]
            if s < target:
                l += 1
            else:
                r -= 1
        return []

class Solution:
    def demo(self, nums, target):
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:  # viz:mid
                return mid
            if nums[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return -1
